自21世纪初激光雷达在DARPA无人车大赛上首次亮相以来，在过去十余年的自动驾驶行业发展浪潮中，被主流认可的激光雷达形态长期属于机械式激光雷达。非重复是扫描是livox &#x3D;&#x3D;览沃&#x3D;&#x3D;在2020年初的CES展会上，Livox面向混合固态时代打造的浩界系列首款激光雷达Horizon横空出世，其7000元级的售价除了给市场提供一剂“激光雷达用得起、买得到”的强心针以外，也给自动驾驶感知算法领域带来了一个新事物：基于旋转棱镜扫描模式下的非重复点云形态。那么下文将会对以重复式扫描的代表机械式激光雷达和非重复式扫描的代表的Livox Mid360激光雷达进行对比分析。
1. 什么是重复式扫描和非重复式扫描？&gt; 

参考- https://zhuanlan.zhihu.com/p/551589651

carla_detector.py（检测 + 跟踪 + 轨迹 完整节点）
使用前替换顶部 ENGINE_PATH 和 OC_SORT_PATH 为你的路径。

#!/usr/bin/env python3&quot;&quot;&quot;CARLA RGB 图像 -&gt; rf-DETR TensorRT 检测 -&gt; OC-SORT 跟踪 + 移动轨迹 -&gt; 发布画框图像 + Detection2DArray。属于 perception_camera 包。用系统 python3 运行（rclpy/cv_bridge/tensorrt/torch/filterpy 在系统 python，不碰 conda）。    source install/setup.bash    ros2 run perception_camera carla_detector.py订阅: /carla/hero/rgb/image  (sensor_msgs/Image)发布: /carla/hero/rgb/detection_image  (画框+ID+轨迹, 给 rviz2)      /carla/hero/detections           (vision_msgs/Detection2DArray, track_id 在 Detection2D.id)&gt;&gt;&gt; 使用前替换下面两个路径为你自己的 &lt;&lt;&lt;注意（踩过的坑，已修复）：  - COCO 类名: 模型 argmax 直接 = COCO ID，不要 +1（+1 会把 car 标成 motorcycle）  - 类别过滤: ALLOWED_CLASSES 必须用 list，np.isin 对 set 返回全 False  - TRT 上下文变量名不能叫 self.context（撞 rclpy Node 只读属性），用 self.trt_context  - humble 的 BoundingBox2D.center 是 vision_msgs/Pose2D，用 center.position.x（不是 center.x）&quot;&quot;&quot;import osimport sysimport numpy as npimport cv2import torchimport tensorrt as trtimport rclpyfrom rclpy.node import Nodefrom rclpy.qos import QoSProfile, QoSReliabilityPolicy, QoSHistoryPolicyfrom sensor_msgs.msg import Imagefrom vision_msgs.msg import Detection2DArray, Detection2D, ObjectHypothesisWithPosefrom cv_bridge import CvBridgefrom collections import OrderedDict, namedtuple, defaultdict# ====== 路径配置（替换为你的）======ENGINE_PATH = os.path.expanduser(&quot;~/models/rf-detr/weights/onnx/rfdetr-medium.engine&quot;)OC_SORT_PATH = os.path.expanduser(&quot;~/models/OC_SORT&quot;)# ==================================sys.path.insert(0, OC_SORT_PATH)from trackers.ocsort_tracker.ocsort import OCSort# ---------- 配置 ----------INPUT_TOPIC = &quot;/carla/hero/rgb/image&quot;OUT_IMAGE_TOPIC = &quot;/carla/hero/rgb/detection_image&quot;OUT_DET_TOPIC = &quot;/carla/hero/detections&quot;RESOLUTION = 576                       # RF-DETR Medium 输入分辨率THRESHOLD = 0.5# ⚠️ 必须用 list！np.isin 对 set 返回全 FalseALLOWED_CLASSES = [1, 2, 3, 4, 6, 8]   # person/bicycle/car/motorcycle/bus/truck (COCO ID = argmax)TRAIL_LEN = 40                         # 轨迹保留点数MEAN = torch.tensor([0.485, 0.456, 0.406])STD = torch.tensor([0.229, 0.224, 0.225])# COCO 类名 (ID -&gt; name)；模型 argmax 直接 = COCO ID，不要 +1COCO_CLASSES = &#123;    1: &quot;person&quot;, 2: &quot;bicycle&quot;, 3: &quot;car&quot;, 4: &quot;motorcycle&quot;, 5: &quot;airplane&quot;, 6: &quot;bus&quot;,    7: &quot;train&quot;, 8: &quot;truck&quot;, 9: &quot;boat&quot;, 10: &quot;traffic light&quot;, 11: &quot;fire hydrant&quot;,    13: &quot;stop sign&quot;, 14: &quot;parking meter&quot;, 15: &quot;bench&quot;, 16: &quot;bird&quot;, 17: &quot;cat&quot;,    18: &quot;dog&quot;, 19: &quot;horse&quot;, 20: &quot;sheep&quot;, 21: &quot;cow&quot;, 22: &quot;elephant&quot;, 23: &quot;bear&quot;,    24: &quot;zebra&quot;, 25: &quot;giraffe&quot;, 27: &quot;backpack&quot;, 28: &quot;umbrella&quot;, 31: &quot;handbag&quot;,    32: &quot;tie&quot;, 33: &quot;suitcase&quot;, 34: &quot;frisbee&quot;, 35: &quot;skis&quot;, 36: &quot;snowboard&quot;,    37: &quot;sports ball&quot;, 38: &quot;kite&quot;, 39: &quot;baseball bat&quot;, 40: &quot;baseball glove&quot;,    41: &quot;skateboard&quot;, 42: &quot;surfboard&quot;, 43: &quot;tennis racket&quot;, 44: &quot;bottle&quot;,    46: &quot;wine glass&quot;, 47: &quot;cup&quot;, 48: &quot;fork&quot;, 49: &quot;knife&quot;, 50: &quot;spoon&quot;, 51: &quot;bowl&quot;,    52: &quot;banana&quot;, 53: &quot;apple&quot;, 54: &quot;sandwich&quot;, 55: &quot;orange&quot;, 56: &quot;broccoli&quot;,    57: &quot;carrot&quot;, 58: &quot;hot dog&quot;, 59: &quot;pizza&quot;, 60: &quot;donut&quot;, 61: &quot;cake&quot;, 62: &quot;chair&quot;,    63: &quot;couch&quot;, 64: &quot;potted plant&quot;, 65: &quot;bed&quot;, 67: &quot;dining table&quot;, 70: &quot;toilet&quot;,    72: &quot;tv&quot;, 73: &quot;laptop&quot;, 74: &quot;mouse&quot;, 75: &quot;remote&quot;, 76: &quot;keyboard&quot;,    77: &quot;cell phone&quot;, 78: &quot;microwave&quot;, 79: &quot;oven&quot;, 80: &quot;toaster&quot;, 81: &quot;sink&quot;,    82: &quot;refrigerator&quot;, 84: &quot;book&quot;, 85: &quot;clock&quot;, 86: &quot;vase&quot;, 87: &quot;scissors&quot;,    88: &quot;teddy bear&quot;, 89: &quot;hair drier&quot;, 90: &quot;toothbrush&quot;,&#125;_TRT_DTYPE_TO_NP = &#123;    trt.DataType.FLOAT: np.float32, trt.DataType.HALF: np.float16,    trt.DataType.INT32: np.int32, trt.DataType.INT64: np.int64,    trt.DataType.INT8: np.int8, trt.DataType.UINT8: np.uint8,    trt.DataType.BOOL: np.bool_,&#125;def _iou_one_to_many(box, boxes):    &quot;&quot;&quot;box: [x1,y1,x2,y2]; boxes: (N,4)。返回每个的 IoU。&quot;&quot;&quot;    if len(boxes) == 0:        return np.zeros(0)    x1 = np.maximum(box[0], boxes[:, 0])    y1 = np.maximum(box[1], boxes[:, 1])    x2 = np.minimum(box[2], boxes[:, 2])    y2 = np.minimum(box[3], boxes[:, 3])    inter = np.maximum(0, x2 - x1) * np.maximum(0, y2 - y1)    area1 = (box[2] - box[0]) * (box[3] - box[1])    area2 = (boxes[:, 2] - boxes[:, 0]) * (boxes[:, 3] - boxes[:, 1])    return inter / (area1 + area2 - inter + 1e-9)def _color_for(tid):    &quot;&quot;&quot;根据 track_id 生成稳定颜色 (RGB)。&quot;&quot;&quot;    return (int((tid * 53) % 256), int((tid * 97) % 256), int((tid * 151) % 256))class CarlaDetector(Node):    def __init__(self):        super().__init__(&quot;carla_detector&quot;)        self.bridge = CvBridge()        self._frame_count = 0        self._load_engine()        self.tracker = OCSort(det_thresh=THRESHOLD)        self.trails = defaultdict(list)  # track_id -&gt; [(cx, cy), ...]        qos = QoSProfile(            reliability=QoSReliabilityPolicy.BEST_EFFORT,            history=QoSHistoryPolicy.KEEP_LAST, depth=5,        )        self.sub = self.create_subscription(Image, INPUT_TOPIC, self.image_cb, qos)        self.pub_img = self.create_publisher(Image, OUT_IMAGE_TOPIC, 10)        self.pub_det = self.create_publisher(Detection2DArray, OUT_DET_TOPIC, 10)        self.get_logger().info(            f&quot;carla_detector ready (detection+OC-SORT). &quot;            f&quot;sub=&#123;INPUT_TOPIC&#125; pub_img=&#123;OUT_IMAGE_TOPIC&#125; pub_det=&#123;OUT_DET_TOPIC&#125;&quot;        )    def _load_engine(self):        Binding = namedtuple(&quot;Binding&quot;, (&quot;name&quot;, &quot;dtype&quot;, &quot;shape&quot;, &quot;data&quot;))        logger = trt.Logger(trt.Logger.WARNING)        with open(ENGINE_PATH, &quot;rb&quot;) as f:            self.engine = trt.Runtime(logger).deserialize_cuda_engine(f.read())        # ⚠️ 不能用 self.context（撞 rclpy Node 只读属性）        self.trt_context = self.engine.create_execution_context()        self.bindings = OrderedDict()        for name in self.engine:            shape = self.engine.get_tensor_shape(name)            dtype = _TRT_DTYPE_TO_NP[self.engine.get_tensor_dtype(name)]            data = torch.from_numpy(np.empty(shape, dtype=dtype)).cuda()            self.bindings[name] = Binding(name, dtype, shape, data)        self.input_names = [n for n in self.bindings                            if self.engine.get_tensor_mode(n) == trt.TensorIOMode.INPUT]        self.binding_addrs = [int(self.bindings[n].data.data_ptr()) for n in self.bindings]        self.get_logger().info(f&quot;engine loaded: inputs=&#123;self.input_names&#125;&quot;)    def _preprocess(self, img_rgb):        h, w = img_rgb.shape[:2]        t = torch.from_numpy(img_rgb).float().permute(2, 0, 1) / 255.0        t = torch.nn.functional.interpolate(            t.unsqueeze(0), size=(RESOLUTION, RESOLUTION),            mode=&quot;bilinear&quot;, align_corners=False).squeeze(0)        t[0] = (t[0] - MEAN[0]) / STD[0]        t[1] = (t[1] - MEAN[1]) / STD[1]        t[2] = (t[2] - MEAN[2]) / STD[2]        return t.unsqueeze(0).cuda(), (w, h)    def _infer(self, inp):        self.bindings[self.input_names[0]].data.copy_(inp)        self.trt_context.execute_v2(self.binding_addrs)        torch.cuda.synchronize()        dets = self.bindings[&quot;dets&quot;].data.cpu().numpy()      # (1,300,4) 归一化 cxcywh        labels = self.bindings[&quot;labels&quot;].data.cpu().numpy()  # (1,300,91) logits        return dets, labels    def _postprocess(self, dets, labels, orig_w, orig_h):        logits = labels[0, :, :-1]                                # (300,90) 丢 no-object        scores_all = 1.0 / (1.0 + np.exp(-logits.clip(-88, 88)))  # sigmoid        scores = scores_all.max(axis=-1)        class_ids = scores_all.argmax(axis=-1)                    # = COCO ID (不加 +1)        keep = scores &gt; THRESHOLD        keep = np.logical_and(keep, np.isin(class_ids, ALLOWED_CLASSES))  # ⚠️ ALLOWED 用 list        cxcywh = dets[0][keep]        scores = scores[keep]        class_ids = class_ids[keep]        cx, cy, bw, bh = cxcywh[:, 0], cxcywh[:, 1], cxcywh[:, 2], cxcywh[:, 3]        x1 = (cx - bw / 2.0) * orig_w        y1 = (cy - bh / 2.0) * orig_h        x2 = (cx + bw / 2.0) * orig_w        y2 = (cy + bh / 2.0) * orig_h        boxes = np.stack([x1, y1, x2, y2], axis=-1)        return boxes, scores, class_ids    def image_cb(self, msg):        try:            img = self.bridge.imgmsg_to_cv2(msg, desired_encoding=&quot;rgb8&quot;)        except Exception as e:            self.get_logger().warn(f&quot;cv_bridge convert failed: &#123;e&#125;&quot;)            return        inp, (w, h) = self._preprocess(img)        dets_raw, labels = self._infer(inp)        boxes, scores, cids = self._postprocess(dets_raw, labels, w, h)        # 喂给 OC-SORT：dets = [x1,y1,x2,y2,score]（原图坐标）        if len(boxes) &gt; 0:            dets_in = np.concatenate([boxes, scores.reshape(-1, 1)], axis=1)        else:            dets_in = np.empty((0, 5))        tracks = self.tracker.update(dets_in, (h, w), (h, w))  # (N,5): [x1,y1,x2,y2,track_id]        ann = img.copy()        da = Detection2DArray()        da.header = msg.header        for trk in tracks:            x1, y1, x2, y2, tid = trk            x1i, y1i, x2i, y2i = int(x1), int(y1), int(x2), int(y2)            tid = int(tid)            # 匹配回检测拿类别            cls_name = &quot;obj&quot;            best, best_iou = -1, 0.0            if len(boxes) &gt; 0:                ious = _iou_one_to_many(np.array([x1, y1, x2, y2]), boxes)                best = int(ious.argmax())                best_iou = float(ious[best])                if best_iou &gt; 0.3:                    coco_id = int(cids[best])                    cls_name = COCO_CLASSES.get(coco_id, f&quot;id&#123;coco_id&#125;&quot;)            color = _color_for(tid)            # 轨迹            cx, cy = (x1i + x2i) // 2, (y1i + y2i) // 2            self.trails[tid].append((cx, cy))            if len(self.trails[tid]) &gt; TRAIL_LEN:                self.trails[tid].pop(0)            pts = self.trails[tid]            for i in range(1, len(pts)):                cv2.line(ann, pts[i - 1], pts[i], color, 2)            # 框 + 标签            cv2.rectangle(ann, (x1i, y1i), (x2i, y2i), color, 2)            cv2.putText(ann, f&quot;&#123;cls_name&#125;:&#123;tid&#125;&quot;, (x1i, max(0, y1i - 6)),                        cv2.FONT_HERSHEY_SIMPLEX, 0.5, color, 1)            # Detection2D（track_id 写入 id 字段）            d = Detection2D()            d.header = msg.header            d.id = str(tid)            d.bbox.center.position.x = float((x1 + x2) / 2.0)   # vision_msgs/Pose2D: center.position.x            d.bbox.center.position.y = float((y1 + y2) / 2.0)            d.bbox.size_x = float(x2 - x1)            d.bbox.size_y = float(y2 - y1)            if best &gt;= 0 and best_iou &gt; 0.3:                hyp = ObjectHypothesisWithPose()                hyp.hypothesis.class_id = str(int(cids[best]))                hyp.hypothesis.score = float(scores[best])                d.results.append(hyp)            da.detections.append(d)        out_msg = self.bridge.cv2_to_imgmsg(ann, encoding=&quot;rgb8&quot;)        out_msg.header = msg.header        self.pub_img.publish(out_msg)        self.pub_det.publish(da)        self._frame_count += 1        if self._frame_count % 30 == 0:            self.get_logger().info(                f&quot;frame &#123;self._frame_count&#125;: &#123;len(boxes)&#125; dets, &#123;len(tracks)&#125; tracks&quot;)def main():    rclpy.init()    node = CarlaDetector()    try:        rclpy.spin(node)    except KeyboardInterrupt:        pass    node.destroy_node()    rclpy.shutdown()if __name__ == &quot;__main__&quot;:    main()

