oise_lon_stddev&quot;: 0.0,                &quot;noise_alt_bias&quot;: 0.0,                &quot;noise_lat_bias&quot;: 0.0,                &quot;noise_lon_bias&quot;: 0.0            &#125;        &#125;,        &#123;            &quot;type&quot;: &quot;sensor.other.imu&quot;,            &quot;id&quot;: &quot;imu&quot;,            &quot;spawn_point&quot;: &#123;&quot;x&quot;: 2.0, &quot;y&quot;: 0.0, &quot;z&quot;: 2.0, &quot;roll&quot;: 0.0, &quot;pitch&quot;: 0.0, &quot;yaw&quot;: 0.0&#125;,            &quot;attributes&quot;: &#123;                &quot;noise_accel_stddev_x&quot;: 0.0,                &quot;noise_accel_stddev_y&quot;: 0.0,                &quot;noise_accel_stddev_z&quot;: 0.0,                &quot;noise_gyro_stddev_x&quot;: 0.0,                &quot;noise_gyro_stddev_y&quot;: 0.0,                &quot;noise_gyro_stddev_z&quot;: 0.0,                &quot;noise_gyro_bias_x&quot;: 0.0,                &quot;noise_gyro_bias_y&quot;: 0.0,                &quot;noise_gyro_bias_z&quot;: 0.0            &#125;        &#125;    ]&#125;
